"use strict";
(function(){
const $=id=>document.getElementById(id),button=Editor.button;
const originalLoad=window.loadConfig,originalSave=window.saveConfig;window.loadConfig=function(){const c=originalLoad();c.rentals=(c.rentals||[]).filter(r=>r.id!=='uber');c.rentals.push({id:'uber',name:'Uber',type:'VAN',collection:'0001-01-01',return:'9999-12-31',system:true});return c;};window.saveConfig=function(c){const clean={...c,rentals:(c.rentals||[]).filter(r=>r.id!=='uber')};originalSave(clean);};
const renderConfig=window.renderConfig;window.renderConfig=function(){renderConfig();document.querySelectorAll('input[aria-label="Rental name"]').forEach(input=>{if(input.value==='Uber')input.closest('tr').remove();});};
const apply=Editor.apply;Editor.apply=function(day){apply(day);day.rentals=(day.rentals||[]).filter(r=>r.id!=='uber'||r.rows.some(row=>row.editorStop||row.editorJob));[day.truck,day.van,...day.rentals].filter(Boolean).forEach(run=>run.rows.forEach(row=>{if(row.editorJob)row.transfers=row.transfers.replace(' | Dump ',' | Onsite Time: ');}));return day;};
const plan=RunEngine.plan;RunEngine.plan=function(items,jobs){const result=plan(items,jobs);result.rows.forEach(row=>{if(row.editorJob)row.transfers=row.transfers.replace(' | Dump ',' | Onsite Time: ');});return result;};
Editor.manual=function(day){const info=prompt('Job number / description');if(!info)return;const time=prompt('Onsite Time (HH:MM). Vehicle is required one hour before and one hour after.');if(!Number.isFinite(RunEngine.minutes(time))){alert('Enter a valid Onsite Time in HH:MM format.');return;}Editor.state().manual.push({info,time,date:Editor.dateKey(day),key:'manual:'+Date.now()+Math.random()});Editor.refresh();};
Editor.resetDay=function(day){const key=Editor.dateKey(day);if(!confirm('Reset this day to its default vehicle allocation and run order? Base jobs will return to unassigned.'))return;delete Editor.state().stops[key];delete Editor.state().orders[key];Object.entries(Editor.state().assignments).forEach(([assignmentKey,vehicle])=>{if(Editor.state().jobDates[assignmentKey]===key)delete Editor.state().assignments[assignmentKey];});Editor.refresh();};
function rentalEmoji(id){const list=(loadConfig().rentals||[]).filter(r=>r.id!=='uber');const index=list.findIndex(r=>r.id===id);return index>=0&&index<6?['1️⃣','2️⃣','3️⃣','4️⃣','5️⃣','6️⃣'][index]:'';}
Editor.rentalEmoji=rentalEmoji;
function icon(id){return id==='truck'?'🚚':id==='van'?'🚐':id==='uber'?'🚕':rentalEmoji(id)||'🚗';}
function moveButton(id,label,fn){const b=button(icon(id),fn);b.title=label;b.setAttribute('aria-label',label);return b;}
function vehicleButtons(day,currentId,row){const actions=document.createDocumentFragment();Editor.ids(day).forEach(target=>{if(target===currentId)return;const label='Move to '+Editor.name(target);const handler=()=>row.editorJob?Editor.assign(day,day.editorJobs.find(j=>j.key===row.editorJob),target):Editor.move(day,row,target);actions.append(moveButton(target,label,handler));});return actions;}
function orderButtons(day,id,row,stops){const pos=stops.indexOf(row),up=button('🔼',()=>Editor.order(day,id,row.editorStop,stops[pos-1].editorStop)),down=button('🔽',()=>Editor.order(day,id,row.editorStop,stops[pos+2]?stops[pos+2].editorStop:null));up.title='Move stop earlier';up.setAttribute('aria-label','Move stop earlier');down.title='Move stop later';down.setAttribute('aria-label','Move stop later');up.disabled=pos===0;down.disabled=pos===stops.length-1;return [up,down];}
function renderSpecialRun(day,id,run,venues){const wrap=document.createElement('div');wrap.className='special-run';const title=document.createElement('div');title.className='run-title';title.textContent=Editor.name(id).toUpperCase()+' RUN — '+day.date.toLocaleDateString('en-AU',{weekday:'short',day:'2-digit',month:'2-digit',year:'numeric'});wrap.append(title);const table=document.createElement('table');table.className='schedule-table';table.innerHTML='<thead><tr><th>Time</th><th>Site from</th><th>Site to</th><th>Onsite contact (from)</th><th>Onsite contact (to)</th></tr></thead>';const body=document.createElement('tbody');table.append(body);const stops=run.rows.filter(r=>r.editorStop);run.rows.forEach(row=>{if(!row.editorStop&&!row.editorJob)return;const tr=document.createElement('tr');const from=row.siteFrom||row.site||'';const to=row.siteTo||'';const contactFrom=(venues.get(from)||{}).contact||'';const contactTo=(venues.get(to)||{}).contact||'';tr.innerHTML='<td>'+escapeAttr(row.time)+'</td><td>'+escapeAttr(from)+'</td><td>'+escapeAttr(to)+'</td><td>'+escapeAttr(contactFrom)+'</td><td>'+escapeAttr(contactTo)+'</td>';const siteCell=tr.cells[1];const actions=document.createElement('div');actions.className='run-actions';if(row.editorStop){actions.append(...orderButtons(day,id,row,stops));actions.append(vehicleButtons(day,id,row));}if(row.editorJob){const job=day.editorJobs.find(j=>j.key===row.editorJob);if(job)actions.append(vehicleButtons(day,id,row),button('❌',()=>Editor.unassign(job)));}siteCell.append(actions);body.append(tr);});wrap.append(table);return wrap;}
const render=window.renderSchedule;window.renderSchedule=function(schedule){render(schedule);document.querySelectorAll('#scheduleOutput .day').forEach((article,di)=>{const day=schedule[di];if(!day)return;const venues=venueMap(loadConfig());const pair=article.querySelector('.vehicle-pair');const special=document.createElement('div');special.className='vehicle-scroll special-runs';const uber=(day.rentals||[]).find(r=>r.id==='uber');const rentalRuns=(day.rentals||[]).filter(r=>r.id!=='uber'&&r.rows&&r.rows.length);const specialRuns=[];if(uber&&uber.rows.length)specialRuns.push(['uber',uber]);rentalRuns.forEach(r=>specialRuns.push([r.id,r]));specialRuns.forEach(([id,run])=>special.append(renderSpecialRun(day,id,run,venues)));if(specialRuns.length&&pair)pair.after(special);const runs=[['truck',day.truck],['van',day.van]].filter(([,run])=>run);const tables=article.querySelectorAll('.vehicle-pair .schedule-table');runs.forEach(([id,run],ri)=>{const table=tables[ri];if(!table)return;const stops=run.rows.filter(r=>r.editorStop);run.rows.forEach((row,index)=>{const tr=table.tBodies[0].rows[index];if(!tr||(!row.editorStop&&!row.editorJob))return;const siteCell=tr.cells[1];if(!siteCell)return;const actions=document.createElement('div');actions.className='run-actions';if(row.editorStop)actions.append(...orderButtons(day,id,row,stops));actions.append(vehicleButtons(day,id,row));if(row.editorStop&&id==='uber')actions.append(button('Remove from Uber',()=>{const state=Editor.state(),key=Editor.dateKey(day);if(state.stops[key])delete state.stops[key][row.editorStop];if(state.orders[key])delete state.orders[key].uber;Editor.refresh();}));siteCell.append(actions);});});const dayActions=article.querySelector('.day-actions');if(dayActions)dayActions.append(button('↩️ Reset day to defaults',()=>Editor.resetDay(day)));article.querySelectorAll('.warning.base button').forEach(b=>{const id=b.textContent==='Add to Truck'?'truck':b.textContent==='Add to Van'?'van':b.textContent==='Add to Uber'?'uber':null;if(id){b.title=b.textContent;b.setAttribute('aria-label',b.textContent);b.textContent=icon(id);}});article.querySelectorAll('.warning.base').forEach(bucket=>{const node=Array.from(bucket.childNodes).find(n=>n.nodeType===Node.TEXT_NODE);if(node)node.textContent=node.textContent.replace(/ at ([0-9: APMapm]+)$/, ' | Onsite Time: $1');});});};
const textarea=$('dumpInput'),panel=textarea.closest('section'),details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Paste manually';details.append(summary);textarea.before(details);details.append(textarea);textarea.rows=3;textarea.style.minHeight='70px';textarea.style.height='70px';textarea.setAttribute('aria-label','Multiline Dump data');
const loaded=document.createElement('p');loaded.setAttribute('role','status');details.before(loaded);function describe(){if(!textarea.value.trim()){loaded.textContent='No import data loaded.';return;}try{const rows=parseDumpText(textarea.value),dates=Array.from(new Set(rows.map(r=>r.dateText)));loaded.textContent='Data loaded: '+rows.length+' records'+(dates.length?' — '+dates[0]+(dates.length>1?' to '+dates[dates.length-1]:'')+'.':'')+' Review before updating the saved schedule.';}catch(e){loaded.textContent='Text loaded. '+e.message;}}textarea.addEventListener('input',describe);
const paste=button('Paste from clipboard',async()=>{try{if(!navigator.clipboard||!navigator.clipboard.readText||!window.isSecureContext)throw Error('Clipboard reading unavailable');const text=await navigator.clipboard.readText();if(!text.trim())throw Error('Clipboard is empty');textarea.value=text;describe();details.open=false;}catch(e){details.open=true;textarea.focus();loaded.textContent='Clipboard access unavailable or denied. Press Ctrl+V / Cmd+V in the small box below. '+e.message;}});details.before(paste);
const clearButton=$('clearDumpBtn');if(clearButton)clearButton.addEventListener('click',()=>{textarea.value='';describe();});
describe();
window.renderConfig();
})();
